@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class ItemDescription {
  + Description : string
  + Dimensions : string
  + Weight : float
}

class ScheduledPickup {
  + PickupTime : time
  + StreetAddress : string
}

class Vehicle {
  + StorageSpace : float
}

class PickupRoute {
  + Day : date
}

class VolunteerDriver {
  + AvailableDays : string[]
}

class SecondHandArticle {
  + Description : string
  + Category : string
}

class FoodItem {}

class DistributionCenter {
  + Location : string
}

class Client {
  + HomeAddress : string
  + NeededCategories : string[]
}

class H2SLocation {
  + City : string
}

class H2SEmployee {
  + Name : string
}

class FoodBank {
  + Name : string
}

H2SLocation "1" -- "*" DistributionCenter
H2SLocation "1" -- "*" VolunteerDriver
H2SLocation "1" -- "*" H2SEmployee
H2SLocation "1" -- "*" Vehicle

Resident "1" -- "*" ScheduledPickup
Resident "1" -- "*" Client
ScheduledPickup "1" -- "1" ItemDescription
ScheduledPickup "1" -- "0..1" SecondHandArticle
ScheduledPickup "1" -- "0..1" FoodItem

Vehicle "1" -- "*" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute
PickupRoute "1" -- "*" ScheduledPickup

DistributionCenter "1" -- "*" SecondHandArticle : receives
DistributionCenter "1" -- "*" H2SEmployee : employs
H2SEmployee "1" -- "*" SecondHandArticle : examines
H2SEmployee "1" -- "*" Client : calls

SecondHandArticle "*" -- "1" DistributionCenter : dropped off at
FoodItem "*" -- "1" FoodBank : dropped off at

VolunteerDriver "1" -- "*" SecondHandArticle : delivers
@enduml

